import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, useWindowDimensions, type ViewStyle } from "react-native";
import { Canvas, Circle, Group, Line, Oval, Points, RadialGradient, RoundedRect, vec } from "@shopify/react-native-skia";
import { runOnJS, useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  CRADLE_DEFAULTS,
  createCradle,
  pickBall,
  stepCradleFixed,
  type CradleConfig,
  type CradlePointer,
  type CradleState,
} from "./cradleMath";
import {
  BALL_BASE, BALL_R, BALL_RIM, BASE_SIDE, BASE_TOP, CHROME_STOPS, CRADLE_BACKGROUND, CRADLE_H, CRADLE_W,
  FRAME_BAR, FRAME_EDGE, FRAME_POST, PIVOT_DX, PIVOT_Y, REST_BALL_Y, SHADOW_Y, SPECULAR, STRING_COLOR,
  STRING_LEN, pivotX,
} from "./cradleDesign";

export type NewtonsCradleProps = {
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "grab" | "release" | "collision") => void;
  label?: string;
  style?: ViewStyle;
};

function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

const INDICES = [0, 1, 2, 3, 4];

function Ball({ sim, frame, i }: { sim: ReturnType<typeof useSharedValue<CradleState>>; frame: ReturnType<typeof useSharedValue<number>>; i: number }) {
  const cx = useDerivedValue(() => {
    frame.value;
    return pivotX(i) + STRING_LEN * Math.sin(sim.value.th[i]);
  });
  const cy = useDerivedValue(() => {
    frame.value;
    return PIVOT_Y + STRING_LEN * Math.cos(sim.value.th[i]);
  });
  const gradientCenter = useDerivedValue(() => ({ x: cx.value - BALL_R * 0.35, y: cy.value - BALL_R * 0.42 }));
  const shadowX = useDerivedValue(() => cx.value - BALL_R * 0.9);
  const shadowOpacity = useDerivedValue(() => Math.max(0.05, 0.2 - ((cy.value - REST_BALL_Y) / 150) * 0.15));
  return (
    <>
      <Oval x={shadowX} y={SHADOW_Y} width={BALL_R * 1.8} height={7} color="#3a2f22" opacity={shadowOpacity} />
      <Circle cx={cx} cy={cy} r={BALL_R} color={BALL_BASE}>
        <RadialGradient c={gradientCenter} r={BALL_R * 1.25} colors={[...CHROME_STOPS]} />
      </Circle>
      <Circle cx={cx} cy={cy} r={BALL_R} color={BALL_RIM} style="stroke" strokeWidth={1} opacity={0.65} />
      <Circle cx={cx} cy={cy} r={BALL_R * 0.17} color={SPECULAR} />
    </>
  );
}

export function NewtonsCradle({
  slowMotion = false,
  reducedMotion,
  onFeedback,
  label = "Newton's cradle",
  style,
}: NewtonsCradleProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const cfg: CradleConfig = useMemo(
    () => ({
      pivotX: new Float32Array(INDICES.map(pivotX)),
      pivotY: PIVOT_Y,
      lengthPx: STRING_LEN,
      ballRadiusPx: BALL_R,
      pixelsPerMeter: STRING_LEN / CRADLE_DEFAULTS.lengthM,
    }),
    [],
  );
  const opts = useMemo(() => CRADLE_DEFAULTS, []);
  /* The design space is 576x380 so the full swing fits; scale it down to the
     host width. Pointer coordinates map back into design space by / scale. */
  const { width: winW } = useWindowDimensions();
  const scale = Math.min(1, (winW - 48) / CRADLE_W);
  const dispW = CRADLE_W * scale;
  const dispH = CRADLE_H * scale;
  const sim = useSharedValue<CradleState>(createCradle(opts));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<CradlePointer>({ id: 0, x: 0, y: 0, ball: -1 });
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const lastClick = useSharedValue(-10);
  const latest = useRef({ reduce, onFeedback });
  latest.current = { reduce, onFeedback };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    reduceM.value = reduce;
    sim.value = createCradle(opts);
    frame.value = frame.value + 1;
  }, [reduce, reduceM, sim, frame, opts]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          const s = sim.value;
          const x = evt.nativeEvent.locationX / scale;
          const y = evt.nativeEvent.locationY / scale;
          const ball = pickBall(s, cfg, x, y, BALL_R * 2.4);
          pointer.value = { id: 1, x, y, ball };
          if (ball >= 0) latest.current.onFeedback?.("grab");
        },
        onPanResponderMove: (evt) => {
          const p = pointer.value;
          if (p.ball >= 0) pointer.value = { ...p, x: evt.nativeEvent.locationX / scale, y: evt.nativeEvent.locationY / scale };
        },
        onPanResponderRelease: () => {
          if (pointer.value.ball >= 0) latest.current.onFeedback?.("release");
          pointer.value = { id: 1, x: 0, y: 0, ball: -1 };
        },
        onPanResponderTerminate: () => {
          pointer.value = { id: 1, x: 0, y: 0, ball: -1 };
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [pointer, sim, cfg],
  );

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const s = sim.value;
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    const ptrs = pointer.value.ball >= 0 ? [pointer.value] : [];
    stepCradleFixed(s, cfg, dt * (slowM.value ? 0.25 : 1), ptrs, opts);
    if (s.lastCollisionAt > lastClick.value + 0.08) {
      lastClick.value = s.lastCollisionAt;
      const cb = latest.current.onFeedback;
      if (cb) runOnJS(cb)("collision");
    }
    frame.value = frame.value + 1;
  });

  const strings = useDerivedValue(() => {
    frame.value;
    const s = sim.value;
    const out: { x: number; y: number }[] = [];
    for (let i = 0; i < s.th.length; i++) {
      const cx = cfg.pivotX[i] + STRING_LEN * Math.sin(s.th[i]);
      const cy = PIVOT_Y + STRING_LEN * Math.cos(s.th[i]);
      for (const side of [-1, 1]) {
        const ax = cfg.pivotX[i] + side * PIVOT_DX;
        const dx = cx - ax;
        const dy = cy - PIVOT_Y;
        const d = Math.hypot(dx, dy) || 1;
        out.push({ x: ax, y: PIVOT_Y });
        out.push({ x: ax + (dx / d) * (d - BALL_R * 0.55), y: PIVOT_Y + (dy / d) * (d - BALL_R * 0.55) });
      }
    }
    return out;
  });

  return (
    <View
      style={[{ width: dispW, height: dispH }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: dispW, height: dispH }}>
        <Group transform={[{ scale }]}>
        <RoundedRect x={0} y={0} width={CRADLE_W} height={CRADLE_H} r={18} color={CRADLE_BACKGROUND} />
        <RoundedRect x={188} y={338} width={200} height={18} r={4} color={BASE_SIDE} />
        <RoundedRect x={188} y={336} width={200} height={9} r={3} color={BASE_TOP} />
        <Line p1={vec(208, 340)} p2={vec(218, 46)} color={FRAME_POST} style="stroke" strokeWidth={7} strokeCap="round" />
        <Line p1={vec(368, 340)} p2={vec(358, 46)} color={FRAME_POST} style="stroke" strokeWidth={7} strokeCap="round" />
        <RoundedRect x={202} y={36} width={172} height={11} r={4} color={FRAME_BAR} />
        <RoundedRect x={202} y={44} width={172} height={4} r={2} color={FRAME_EDGE} opacity={0.55} />
        <Points points={strings} mode="lines" color={STRING_COLOR} style="stroke" strokeWidth={1.4} strokeCap="round" />
        {INDICES.map((i) => (
          <Ball key={i} sim={sim} frame={frame} i={i} />
        ))}
        </Group>
      </Canvas>
    </View>
  );
}

/* Newton's Cradle shared simulation. Pure TypeScript, no closures over
   component state, so Reanimated can run every function on the UI thread.
   Model: N identical rigid pendulums on taut strings (circular constraint),
   RK4 for free swing, sequential pairwise impulse resolution between
   neighbours for collisions. Equal masses swap the normal velocity component
   at restitution 1, so a left-to-right sweep propagates momentum through the
   line and produces the toy's n-in / n-out behaviour. Restitution is kept
   just under 1 and a light viscous drag bleeds energy so the cradle settles.
   This is an impulse solver over separated contacts, not a finite-element
   contact model - the same idealisation the real toy approximates. */

export type CradlePointer = { id: number; x: number; y: number; ball: number };

export type CradleConfig = {
  /* pivot x per ball (px), shared pivot y, string length and ball radius (px) */
  pivotX: Float32Array;
  pivotY: number;
  lengthPx: number;
  ballRadiusPx: number;
  pixelsPerMeter: number;
};

export type CradlePhysics = {
  balls: number;
  gravity: number;
  lengthM: number;
  damping: number;
  restitution: number;
  fixedDt: number;
  grabRate: number;
  velocitySmoothing: number;
  maxOmega: number;
  maxTheta: number;
  grabDeadband: number;
  restOmega: number;
  restTheta: number;
};

export const CRADLE_DEFAULTS: CradlePhysics = {
  balls: 5,
  gravity: 9.81,
  lengthM: 0.14,
  damping: 0.05,
  restitution: 0.99,
  fixedDt: 1 / 480,
  grabRate: 18,
  velocitySmoothing: 0.03,
  maxOmega: 16,
  maxTheta: 1.25,
  grabDeadband: 0.06,
  restOmega: 0.05,
  restTheta: 0.02,
};

export type CradleState = {
  th: Float32Array;
  om: Float32Array;
  grabbed: Float32Array;
  time: number;
  acc: number;
  resting: number;
  sweep: number;
  lastCollisionAt: number;
};

export function createCradle(opts: CradlePhysics): CradleState {
  "worklet";
  return {
    th: new Float32Array(opts.balls),
    om: new Float32Array(opts.balls),
    grabbed: new Float32Array(opts.balls),
    time: 0,
    acc: 0,
    resting: 1,
    sweep: 0,
    lastCollisionAt: -10,
  };
}

export function resetCradle(s: CradleState) {
  "worklet";
  s.th.fill(0);
  s.om.fill(0);
  s.grabbed.fill(0);
  s.time = 0;
  s.acc = 0;
  s.resting = 1;
  s.lastCollisionAt = -10;
}

export function ballCenter(s: CradleState, cfg: CradleConfig, i: number, out: number[]) {
  "worklet";
  out[0] = cfg.pivotX[i] + cfg.lengthPx * Math.sin(s.th[i]);
  out[1] = cfg.pivotY + cfg.lengthPx * Math.cos(s.th[i]);
}

export function pickBall(s: CradleState, cfg: CradleConfig, x: number, y: number, maxDistPx: number): number {
  "worklet";
  let best = -1;
  let bestD = maxDistPx;
  const c = [0, 0];
  for (let i = 0; i < s.th.length; i++) {
    ballCenter(s, cfg, i, c);
    const d = Math.hypot(x - c[0], y - c[1]);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

function pendAccel(th: number, om: number, p: CradlePhysics): number {
  "worklet";
  return -(p.gravity / p.lengthM) * Math.sin(th) - p.damping * om;
}

function rk4(s: CradleState, i: number, dt: number, p: CradlePhysics) {
  "worklet";
  const th0 = s.th[i], om0 = s.om[i];
  const k1t = om0, k1o = pendAccel(th0, om0, p);
  const k2t = om0 + (dt / 2) * k1o, k2o = pendAccel(th0 + (dt / 2) * k1t, om0 + (dt / 2) * k1o, p);
  const k3t = om0 + (dt / 2) * k2o, k3o = pendAccel(th0 + (dt / 2) * k2t, om0 + (dt / 2) * k2o, p);
  const k4t = om0 + dt * k3o, k4o = pendAccel(th0 + dt * k3t, om0 + dt * k3o, p);
  s.th[i] = th0 + (dt / 6) * (k1t + 2 * k2t + 2 * k3t + k4t);
  s.om[i] = om0 + (dt / 6) * (k1o + 2 * k2o + 2 * k3o + k4o);
}

/* Resolve one touching pair. n points from i to j. Velocities are in m/s;
   the normal component is exchanged with restitution, tangential kept.
   A grabbed ball is treated as infinitely massive (the hand holds it). */
function resolvePair(s: CradleState, cfg: CradleConfig, p: CradlePhysics, i: number, j: number) {
  "worklet";
  const ci = [0, 0], cj = [0, 0];
  ballCenter(s, cfg, i, ci);
  ballCenter(s, cfg, j, cj);
  let nx = cj[0] - ci[0], ny = cj[1] - ci[1];
  let d = Math.hypot(nx, ny);
  const minD = 2 * cfg.ballRadiusPx * 0.999;
  if (d >= minD) return;
  if (d < 1e-6) {
    nx = 1;
    ny = 0;
    d = 1e-6;
  } else {
    nx /= d;
    ny /= d;
  }
  const L = p.lengthM;
  const uiX = Math.cos(s.th[i]), uiY = -Math.sin(s.th[i]);
  const ujX = Math.cos(s.th[j]), ujY = -Math.sin(s.th[j]);
  const vnI = L * s.om[i] * (uiX * nx + uiY * ny);
  const vnJ = L * s.om[j] * (ujX * nx + ujY * ny);
  const gi = s.grabbed[i] > 0.5;
  const gj = s.grabbed[j] > 0.5;
  const e = p.restitution;
  if (vnI - vnJ > 0 && !(gi && gj)) {
    let nI = vnI, nJ = vnJ;
    if (gi) nJ = (1 + e) * vnI - e * vnJ;
    else if (gj) nI = (1 + e) * vnJ - e * vnI;
    else {
      nI = ((1 - e) * vnI + (1 + e) * vnJ) / 2;
      nJ = ((1 + e) * vnI + (1 - e) * vnJ) / 2;
    }
    if (!gi) s.om[i] += ((nI - vnI) * (uiX * nx + uiY * ny)) / L;
    if (!gj) s.om[j] += ((nJ - vnJ) * (ujX * nx + ujY * ny)) / L;
    s.lastCollisionAt = s.time;
  }
  /* positional de-overlap: free balls share the correction, a grabbed ball stays */
  const overlap = 2 * cfg.ballRadiusPx - d;
  if (overlap > 0) {
    const shareI = gi ? 0 : gj ? 1 : 0.5;
    const shareJ = gj ? 0 : gi ? 1 : 0.5;
    const mv = (k: number, mx: number, my: number) => {
      const c = [0, 0];
      ballCenter(s, cfg, k, c);
      s.th[k] = Math.atan2(c[0] + mx - cfg.pivotX[k], c[1] + my - cfg.pivotY);
    };
    if (shareI > 0) mv(i, -nx * overlap * shareI, -ny * overlap * shareI);
    if (shareJ > 0) mv(j, nx * overlap * shareJ, ny * overlap * shareJ);
  }
}

/* Balls held this frame, mapped from active pointers. Pulling the k-th ball
   from an end scoops the whole outer group, matching how the toy is grabbed. */
function applyGrabs(s: CradleState, cfg: CradleConfig, p: CradlePhysics, dt: number, pointers: CradlePointer[]) {
  "worklet";
  const held = new Float32Array(s.th.length);
  for (let pi = 0; pi < pointers.length; pi++) {
    const ptr = pointers[pi];
    if (ptr.ball < 0 || ptr.ball >= s.th.length) continue;
    const b = ptr.ball;
    const target = Math.atan2(ptr.x - cfg.pivotX[b], ptr.y - cfg.pivotY);
    const clamped = Math.max(-p.maxTheta, Math.min(p.maxTheta, target));
    let lo = b, hi = b;
    if (clamped < -p.grabDeadband) {
      lo = 0;
      hi = b;
    } else if (clamped > p.grabDeadband) {
      lo = b;
      hi = s.th.length - 1;
    }
    const ease = 1 - Math.exp(-p.grabRate * dt);
    const blend = 1 - Math.exp(-dt / p.velocitySmoothing);
    for (let k = lo; k <= hi; k++) {
      held[k] = 1;
      const before = s.th[k];
      const next = before + (clamped - before) * ease;
      s.om[k] += ((next - before) / dt - s.om[k]) * blend;
      s.th[k] = next;
      s.grabbed[k] = 1;
    }
  }
  for (let k = 0; k < s.th.length; k++) {
    if (s.grabbed[k] > 0.5 && held[k] < 0.5) {
      s.grabbed[k] = 0;
      s.om[k] = Math.max(-p.maxOmega, Math.min(p.maxOmega, s.om[k]));
    }
  }
}

function settle(s: CradleState, p: CradlePhysics) {
  "worklet";
  let worstO = 0, worstT = 0;
  for (let i = 0; i < s.th.length; i++) {
    worstO = Math.max(worstO, Math.abs(s.om[i]));
    worstT = Math.max(worstT, Math.abs(s.th[i]));
  }
  if (worstO < p.restOmega && worstT < p.restTheta) {
    for (let i = 0; i < s.th.length; i++) {
      s.th[i] *= 0.92;
      s.om[i] *= 0.85;
    }
    if (worstO < 0.004 && worstT < 0.002) {
      s.th.fill(0);
      s.om.fill(0);
      s.resting = 1;
    }
  }
}

export function totalEnergy(s: CradleState, p: CradlePhysics): number {
  "worklet";
  let e = 0;
  for (let i = 0; i < s.th.length; i++) {
    e += 0.5 * p.lengthM * p.lengthM * s.om[i] * s.om[i] + p.gravity * p.lengthM * (1 - Math.cos(s.th[i]));
  }
  return e;
}

function substep(s: CradleState, cfg: CradleConfig, p: CradlePhysics, dt: number, pointers: CradlePointer[]) {
  "worklet";
  applyGrabs(s, cfg, p, dt, pointers);
  let anyGrab = false;
  for (let i = 0; i < s.th.length; i++) {
    if (s.grabbed[i] > 0.5) {
      anyGrab = true;
      continue;
    }
    rk4(s, i, dt, p);
  }
  /* sequential pairwise passes; sweep direction alternates per substep so the
     propagation order does not systematically favour one side */
  s.sweep = 1 - s.sweep;
  for (let pass = 0; pass < 3; pass++) {
    if (s.sweep === 0) {
      for (let i = 0; i < s.th.length - 1; i++) resolvePair(s, cfg, p, i, i + 1);
    } else {
      for (let i = s.th.length - 2; i >= 0; i--) resolvePair(s, cfg, p, i, i + 1);
    }
  }
  if (!anyGrab) settle(s, p);
  else s.resting = 0;
  if (!s.resting) s.time += dt;
}

export function stepCradleFixed(
  s: CradleState,
  cfg: CradleConfig,
  dtFrame: number,
  pointers: CradlePointer[],
  opts: CradlePhysics,
) {
  "worklet";
  s.acc += Math.min(dtFrame, 0.05);
  const dt = opts.fixedDt;
  while (s.acc >= dt) {
    substep(s, cfg, opts, dt, pointers);
    s.acc -= dt;
  }
}

/* Convenience for demos and keyboard control: pull a group out over `ms`
   worth of steps then let go. count=1 lifts one ball from the given side. */
export function releaseImpulse(s: CradleState, side: "left" | "right", count: number, angle: number) {
  "worklet";
  const n = s.th.length;
  const a = Math.max(-CRADLE_DEFAULTS.maxTheta, Math.min(CRADLE_DEFAULTS.maxTheta, Math.abs(angle)));
  for (let k = 0; k < count && k < n; k++) {
    const i = side === "left" ? k : n - 1 - k;
    s.th[i] = side === "left" ? -a : a;
    s.om[i] = 0;
    s.grabbed[i] = 0;
  }
  s.resting = 0;
}

/* Layout and palette shared by the Skia source and the Canvas2D preview.
   Viewport invariant: a ball held at the maximum drag angle (maxTheta = 1.25
   rad in cradleMath) must stay fully inside the canvas. The canvas is widened
   (not the swing narrowed) to guarantee it:
     pivotX(0) - STRING_LEN * sin(1.25) - BALL_R = 228 - 205.0 - 15 = 8.0 px
   and symmetric on the right (576 - 8.0 = 568.0). Renderers scale this design
   space down to the host; keep the invariant when retuning. */
export const CRADLE_W = 576;
export const CRADLE_H = 380;
export const CRADLE_BACKGROUND = "#f3efe6";
export const CRADLE_BALLS = 5;
export const BALL_R = 15;
export const PIVOT_Y = 44;
export const STRING_LEN = 216;
export const BALL_SPACING = BALL_R * 2;
export const CENTER_X = CRADLE_W / 2;
export const PIVOT_DX = 5;
export const REST_BALL_Y = PIVOT_Y + STRING_LEN;
export const SHADOW_Y = 332;

export const FRAME_BAR = "#9aa5ae";
export const FRAME_EDGE = "#5c666e";
export const FRAME_POST = "#8b96a0";
export const BASE_TOP = "#8b6b4a";
export const BASE_SIDE = "#6d5238";
export const STRING_COLOR = "#3f4a52";
export const BALL_BASE = "#7d8890";
export const BALL_RIM = "#454f56";
export const CHROME_STOPS = ["#fdfefe", "#c3ccd2", "#5f6a72"] as const;
export const SPECULAR = "rgba(255,255,255,0.95)";

export function pivotX(i: number): number {
  "worklet";
  return CENTER_X + (i - (CRADLE_BALLS - 1) / 2) * BALL_SPACING;
}

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { NewtonsCradle } from "./NewtonsCradle";

export default function Example({ onFeedback }: { onFeedback?: (event: "grab" | "release" | "collision") => void }) {
  const [slow, setSlow] = useState(false),
    [reduce, setReduce] = useState(false);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <NewtonsCradle slowMotion={slow} reducedMotion={reduce} onFeedback={onFeedback} />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular", textAlign: "center", paddingHorizontal: 16 }}>
        Pull a ball back and let go. Grab the second ball from an end to lift two.
      </Text>
    </View>
  );
}
